<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import type { AnaliticoFiltros,MovimientoAnalitico,ReporteAnalitico,TipoComprobanteAnalitico } from '../interfaces/analitico-comprobante.interface'
import { descargarAnaliticoExcel,descargarAnaliticoPdf,generarAnaliticoComprobantes,listarTiposComprobanteAnalitico } from '../services/analitico-comprobante'
const today=new Date(),first=new Date(today.getFullYear(),today.getMonth(),1).toISOString().slice(0,10)
const filters=reactive<AnaliticoFiltros>({fecha_inicio:first,fecha_fin:today.toISOString().slice(0,10),tipo_comprobante_id:0,estado:'TODOS'}),types=ref<TipoComprobanteAnalitico[]>([]),report=ref<ReporteAnalitico|null>(null),expanded=ref<number[]>([]),loading=ref(false),error=ref('')
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo generar el reporte.',money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))
async function generate(){if(filters.fecha_inicio>filters.fecha_fin){error.value='La fecha final no puede ser menor que la fecha inicial.';return}loading.value=true;error.value='';try{report.value=await generarAnaliticoComprobantes({...filters});expanded.value=[]}catch(e){error.value=message(e)}finally{loading.value=false}}
async function download(kind:'pdf'|'excel'){loading.value=true;error.value='';try{await (kind==='pdf'?descargarAnaliticoPdf({...filters}):descargarAnaliticoExcel({...filters}))}catch(e){error.value=message(e)}finally{loading.value=false}}
function toggle(item:MovimientoAnalitico){expanded.value=expanded.value.includes(item.id)?expanded.value.filter(x=>x!==item.id):[...expanded.value,item.id]}
onMounted(async()=>{try{types.value=await listarTiposComprobanteAnalitico()}catch(e){error.value=message(e)}})
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Consistencias de comprobantes</nav><header class="hero"><div class="mark">AC</div><div><small>MIA · FINANZAS · REPORTES</small><h1>Analítico de comprobantes</h1><p>Revisión de cargos, abonos y consistencia contable por comprobante.</p></div><div v-if="report" class="status" :class="report.totales.movimientos_descuadrados?'bad':'good'">{{report.totales.movimientos_descuadrados}} descuadrados</div></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="generate"><label>Desde<input v-model="filters.fecha_inicio" type="date" required></label><label>Hasta<input v-model="filters.fecha_fin" type="date" required></label><label>Tipo de comprobante<select v-model.number="filters.tipo_comprobante_id" required><option :value="0">Seleccione</option><option v-for="x in types" :key="x.id" :value="x.id">{{x.detalle}}</option></select></label><label>Estado<select v-model="filters.estado"><option>TODOS</option><option>ACTIVOS</option><option>INACTIVOS</option></select></label><button :disabled="loading||!filters.tipo_comprobante_id">{{loading?'Procesando…':'Generar reporte'}}</button></form><section v-if="report" class="summary"><div><small>TIPO DE COMPROBANTE</small><b>{{report.cabecera.tipo_comprobante}}</b></div><div><small>MOVIMIENTOS</small><b>{{report.cabecera.cantidad_movimientos}}</b></div><div><small>TOTAL CARGOS</small><b>{{money(report.totales.cargos)}}</b></div><div><small>TOTAL ABONOS</small><b>{{money(report.totales.abonos)}}</b></div><div :class="Math.abs(report.totales.diferencia)>.009?'alert':''"><small>DIFERENCIA</small><b>{{money(report.totales.diferencia)}}</b></div><div class="downloads"><button @click="download('pdf')">PDF</button><button class="excel" @click="download('excel')">Excel</button></div></section><section class="card"><div v-if="!report" class="empty">Seleccione el periodo y tipo de comprobante para iniciar el análisis.</div><div v-else-if="!report.movimientos.length" class="empty">No se encontraron movimientos para los filtros seleccionados.</div><div v-else class="scroll"><table><thead><tr><th></th><th>Comprobante</th><th>Fecha</th><th>Glosa / documento</th><th>Estado</th><th>Cargo</th><th>Abono</th><th>Diferencia</th><th>Consistencia</th></tr></thead><tbody v-for="item in report.movimientos" :key="item.id"><tr><td><button class="open" @click="toggle(item)">{{expanded.includes(item.id)?'−':'+'}}</button></td><td><b>{{item.numero_comprobante}}</b><small>{{item.tipo_comprobante}}</small></td><td>{{item.fecha_comprobante}}</td><td>{{item.glosa}}<small>{{item.tipo_documento}} {{item.numero_documento}}</small></td><td>{{item.activo?'ACTIVO':'INACTIVO'}}</td><td class="number">{{money(item.total_cargo)}}</td><td class="number">{{money(item.total_abono)}}</td><td class="number">{{money(item.diferencia)}}</td><td><span :class="item.cuadrado?'good':'bad'">{{item.cuadrado?'CUADRADO':'DESCUADRADO'}}</span></td></tr><tr v-if="expanded.includes(item.id)" class="detail"><td colspan="9"><table><thead><tr><th>Ítem</th><th>Cuenta</th><th>Analítico</th><th>Centro de costo</th><th>Debe</th><th>Haber</th><th>Observaciones</th></tr></thead><tbody><tr v-for="line in item.detalles" :key="line.item" :class="{issue:line.tiene_error}"><td>{{line.item}}</td><td><b>{{line.cuenta_codigo}}</b><small>{{line.cuenta_descripcion}}</small></td><td>{{line.analitico||'-'}}</td><td>{{line.centro_costo_codigo}} {{line.centro_costo_nombre}}</td><td class="number">{{money(line.cargo)}}</td><td class="number">{{money(line.abono)}}</td><td>{{line.errores.join(', ')||'Sin observaciones'}}</td></tr></tbody></table></td></tr></tbody></table></div></section></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.summary small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.status,.good,.bad{display:inline-block;padding:5px 8px;border-radius:10px;font-size:.48rem;font-weight:800}.good{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.flash{padding:10px;color:#9b3d48;background:#fdebee;font-size:.55rem}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:1fr 1fr 2fr 1fr auto;gap:8px;background:#fff}.filters label{display:grid;gap:4px;color:#607179;font-size:.5rem;font-weight:700}.filters input,.filters select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.52rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.filters>button{align-self:end}.summary{margin-top:11px;display:grid;grid-template-columns:2fr repeat(4,1fr) auto;gap:8px}.summary>div{display:grid;gap:5px;padding:12px;background:#fff}.summary .alert{border-bottom:3px solid #bd4c55}.downloads{display:flex!important;align-items:center}.excel{background:#27875f}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1100px;border-collapse:collapse;font-size:.49rem}th,td{padding:9px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#829096}.number{text-align:right;font-variant-numeric:tabular-nums}.open{width:25px;height:25px;padding:0}.detail>td{padding:12px;background:#edf3f5}.detail table{min-width:900px;background:#fff}.detail th{background:#67808d}.issue{background:#fff1f1}.empty{padding:55px;text-align:center;color:#849198}@media(max-width:850px){.filters,.summary{grid-template-columns:1fr 1fr}.hero{flex-wrap:wrap}}@media(max-width:550px){.filters,.summary{grid-template-columns:1fr}.hero .mark{display:none}}
</style>
